INSERT INTO skill_definitions (code, name, description, world_ordinal, max_level, base_cost_cents, cost_growth, base_seconds, time_growth) VALUES
 ('w1_packing', 'Pakowanie plecaka', 'Co zabrać, a co zostawić w domu. Lekki, dobrze ułożony plecak to szybszy marsz i mniej bólu pleców.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_campfire', 'Rozpalanie ogniska', 'Sucha gałązka, iskra i odrobina cierpliwości. Ciepło i kiełbaska na każdym biwaku.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_trail_signs', 'Znaki szlaków', 'Czerwony, niebieski, zielony, żółty. Odczytujesz oznaczenia na drzewach z pierwszego rzutu oka.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_first_aid', 'Pierwsza pomoc', 'Plaster, bandaż i spokojna głowa przy otarciu, skręceniu czy ukąszeniu.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_boots', 'Dobór butów', 'Dobrze dopasowane buty to połowa udanej wyprawy. Wiesz, kiedy pora na nowe skarpety.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_weather', 'Prognozowanie pogody', 'Chmury, wiatr i zapach deszczu mówią więcej niż niejedna aplikacja.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_cooking', 'Kuchnia turystyczna', 'Zupa z torebki po kilkunastu kilometrach smakuje jak uczta w pięciogwiazdkowej restauracji.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_photo', 'Fotografia z szlaku', 'Złapane światło o poranku, panorama z przełęczy i pamiątki, które zostaną na lata.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_tent', 'Rozbijanie namiotu', 'Szybko, równo i bez zgubionych śledzi. Namiot stoi, zanim zacznie padać.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w1_etiquette', 'Szlakowa etykieta', 'Pozdrowienia na szlaku, ustępowanie drogi i zabieranie śmieci. Dobre imię turysty.', 1, 30, 4, 1.1000, 8, 1.1000),
 ('w2_mushrooms', 'Rozpoznawanie grzybów', 'Prawdziwek czy muchomor? Uczysz się odróżniać jadalne od groźnych, zanim koszyk się napełni.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_herbs', 'Zbieranie ziół i jagód', 'Poziomki, borówki i mięta nad strumieniem. Las karmi tych, którzy znają jego spiżarnię.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_tracking', 'Tropienie zwierząt', 'Odciski racic, połamane gałązki i ślady w runie. Czytasz las jak otwartą książkę.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_woodcutting', 'Rąbanie drewna', 'Równe polana na całą noc. Dobry rąbacz nie męczy się szybciej niż ogień.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_shelter', 'Budowa szałasu', 'Gałęzie, mech i trochę sprytu. Nocleg bez namiotu staje się wygodny.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_fishing', 'Wędkowanie w strumieniu', 'Cichy plusk, cierpliwa ręka i pstrąg na kolację.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_stream_crossing', 'Przeprawa przez potok', 'Mokre kamienie i wartki nurt. Wiesz, gdzie postawić stopę, żeby buty zostały suche.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_night_march', 'Nocny marsz', 'Ciemny las, latarka i spokojny oddech. Idziesz dalej, gdy inni już śpią.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_insects', 'Ochrona przed owadami', 'Kleszcze, komary i bąki nie mają z Tobą szans. Odpowiednie ubranie to podstawa.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w2_silence', 'Leśna cisza', 'Stąpasz bezgłośnie i słyszysz więcej. Zwierzęta przestają Cię zauważać.', 2, 30, 31, 1.1000, 52, 1.1000),
 ('w3_layers', 'Ubiór warstwowy', 'Wełna przy skórze, puch na wierzchu. Zimno traci nad Tobą władzę.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_snow_shelter', 'Schronienie w śniegu', 'Jama, igloo albo zaspa z wejściem pod wiatr. Śnieg potrafi ocalić życie.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_snowshoes', 'Rakiety śnieżne', 'Zamiast zapadać się po pas, suniesz po powierzchni śniegu.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_skiing', 'Narty biegowe', 'Równy rytm, ślizg i oddech. Dystans znika szybciej, niż myślisz.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_dog_sled', 'Zaprzęg psi', 'Psy ciągną, Ty prowadzisz. Zaufanie między człowiekiem a psem to cała tajemnica.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_ice_fishing', 'Połów w przeręblu', 'Wycięta przerębla, haczyk i cisza. Ryby biorą nawet w siarczysty mróz.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_ice_reading', 'Czytanie lodu', 'Wiesz, który lód utrzyma, a który zdradzi. Jedno spojrzenie wystarcza.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_snow_melting', 'Topienie śniegu', 'Woda do picia z białego puchu, bez ryzyka wychłodzenia i marnowania paliwa.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_frostbite', 'Ochrona przed odmrożeniami', 'Palce, nos i policzki bezpieczne mimo mrozu. Wiesz, kiedy trzeba się ogrzać.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w3_whiteout', 'Nawigacja w zamieci', 'Biała ściana wokół, a Ty trzymasz kierunek. Kompas i zimna krew wystarczą.', 3, 30, 611, 1.1000, 1019, 1.1000),
 ('w4_water', 'Gospodarka wodą', 'Każdy łyk liczy się podwójnie. Planujesz zapasy tak, by wystarczyło do następnej oazy.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_oasis', 'Wypatrywanie oaz', 'Zielona plama na horyzoncie, ptaki nad piaskiem i ślady karawan. Wiesz, gdzie szukać wody.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_camel', 'Jazda na wielbłądzie', 'Kołysanie, upór i cierpliwość. Wielbłąd to najlepszy przyjaciel na wydmach.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_sun_protection', 'Ochrona przed słońcem', 'Turban, szerokie rękawy i cień w samo południe. Skwar nie ma wstępu.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_star_navigation', 'Nawigacja po gwiazdach', 'Gdy piasek zatrze ślady, niebo pokaże drogę. Znasz gwiazdozbiory jak własną kieszeń.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_bazaar', 'Targowanie na bazarze', 'Herbata, uśmiech i długa rozmowa o cenie. Tutaj handel to sztuka.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_dunes', 'Marsz po wydmach', 'Sypki piasek, ciężkie nogi i równy krok. Wiesz, którą stroną grzbietu iść.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_sandstorm', 'Przetrwanie burzy piaskowej', 'Szalik na twarz, plecami do wiatru i spokojne czekanie. Burza kiedyś minie.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_cold_nights', 'Zimne noce na pustyni', 'Upał w dzień, mróz w nocy. Wiesz, jak się zabezpieczyć przed obiema.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w4_dried_food', 'Daktyle i suszone zapasy', 'Lekki, pożywny prowiant, który nie psuje się w upale.', 4, 30, 3456, 1.1000, 4573, 1.1000),
 ('w5_machete', 'Torowanie drogi maczetą', 'Rytmiczne cięcia i równy marsz. Ściana zieleni ustępuje, a Ty nie tracisz sił.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_liana_climbing', 'Wspinaczka po lianach', 'Mocny chwyt, pewna stopa i spokojny oddech. Korony drzew stoją otworem.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_rope_bridge', 'Przeprawa mostem z lian', 'Chybotliwa kładka nad przepaścią. Idziesz powoli, ale pewnie.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_edible_plants', 'Rośliny jadalne', 'Owoce, korzenie i orzechy. Wiesz, co zjeść, a czego unikać w tropikach.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_tropical_health', 'Zdrowie w tropikach', 'Wilgoć, owady i gorączka. Znasz sposoby, by choroby omijały Twój obóz.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_rainwater', 'Zbieranie wody deszczowej', 'Liść, naczynie i ulewa. Czysta woda do picia bez wychodzenia z obozu.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_canoe', 'Spływ kajakiem', 'Rwące rzeki i spokojne rozlewiska. Wiosło w dłoni prowadzi tam, gdzie nie ma dróg.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_jungle_listening', 'Nasłuchiwanie dżungli', 'Krzyki ptaków i szelest liści opowiadają, co czai się w pobliżu.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_hammock', 'Nocleg w hamaku', 'Dwa drzewa, lina i moskitiera. Śpisz wysoko nad wilgotną ziemią.', 5, 30, 7904, 1.1000, 7938, 1.1000),
 ('w5_local_speech', 'Mowa lokalnych szlaków', 'Kilka słów, uśmiech i gesty. Mieszkańcy dżungli chętnie zdradzają ukryte ścieżki.', 5, 30, 7904, 1.1000, 7938, 1.1000);
INSERT IGNORE INTO user_skills (user_id, skill_id, level) SELECT u.id, s.id, 0 FROM users u JOIN skill_definitions s ON s.world_ordinal IS NOT NULL;
