-- Umiejetnosci swiatow: po 10 na swiat (world_ordinal), odblokowane po dotarciu do danego swiata.
-- Trudnosc startowa = 40% kosztu i czasu podstawowej umiejetnosci na poziomie wejscia do swiata (10, 23, 43, 63, 83).
ALTER TABLE skill_definitions ADD COLUMN world_ordinal TINYINT UNSIGNED NULL AFTER description;


